// Splits every email into ONE item per valid attachment (PDF / image).
const out = [];
const items = $input.all();
const MIN_IMAGE_BYTES = 8 * 1024; // ignore tiny inline images (logos, signatures)
const extToMime = { pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' };

const pick = (...vals) => vals.find(v => v !== undefined && v !== null && v !== '');
const textOf = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (v.text) return v.text;
  if (Array.isArray(v.value)) {
    return v.value.map(x => x.address ? (x.name ? `${x.name} <${x.address}>` : x.address) : '').join(', ');
  }
  return '';
};

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json;
  const allowed = String(j.allowedMimeTypes || 'application/pdf,image/png,image/jpeg,image/webp')
    .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  const maxBytes = (Number(j.maxFileSizeMB) || 15) * 1024 * 1024;

  const messageId = String(pick(j.id, j.messageId, ''));
  const from = textOf(pick(j.from, j.From, j.headers && j.headers.from));
  const subject = String(pick(j.subject, j.Subject, j.headers && j.headers.subject, '(no subject)'));
  const emailDate = String(pick(j.date, j.Date, j.internalDate ? new Date(Number(j.internalDate)).toISOString() : '', ''));
  const emailLink = messageId ? `https://mail.google.com/mail/u/0/#all/${messageId}` : '';

  const binaries = item.binary || {};
  for (const key of Object.keys(binaries)) {
    const bin = binaries[key];
    const fileName = bin.fileName || key;
    const ext = (fileName.split('.').pop() || '').toLowerCase();
    let mime = String(bin.mimeType || '').toLowerCase();
    if ((!mime || mime === 'application/octet-stream') && extToMime[ext]) mime = extToMime[ext];
    if (!allowed.includes(mime)) continue;

    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    if (buf.length > maxBytes) continue;
    if (mime.startsWith('image/') && buf.length < MIN_IMAGE_BYTES) continue;

    out.push({
      json: { messageId, from, subject, emailDate, emailLink, fileName, mimeType: mime, fileSizeKB: Math.round(buf.length / 1024) },
      binary: { data: { ...bin, mimeType: mime } },
      pairedItem: { item: i },
    });
  }
}
return out;

// Builds the OpenAI request (PDF/image sent as base64, strict JSON schema response).
const cfg = $('⚙️ Workflow Config').first().json;
const model = cfg.aiModel || 'gpt-4o-mini';
const categories = String(cfg.expenseCategories || 'Other').split(',').map(s => s.trim()).filter(Boolean);
const defaultCurrency = String(cfg.defaultCurrency || 'USD').toUpperCase();

const nullableString = { type: ['string', 'null'] };
const nullableNumber = { type: ['number', 'null'] };

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['is_invoice_or_receipt', 'document_type', 'vendor_name', 'invoice_number', 'invoice_date', 'due_date',
             'currency', 'subtotal', 'tax_amount', 'total_amount', 'category', 'description', 'line_items', 'confidence', 'notes'],
  properties: {
    is_invoice_or_receipt: { type: 'boolean' },
    document_type: { type: 'string', enum: ['invoice', 'receipt', 'bill', 'credit_note', 'statement', 'other'] },
    vendor_name: nullableString,
    invoice_number: nullableString,
    invoice_date: nullableString,
    due_date: nullableString,
    currency: nullableString,
    subtotal: nullableNumber,
    tax_amount: nullableNumber,
    total_amount: nullableNumber,
    category: { type: 'string', enum: categories },
    description: nullableString,
    line_items: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['description', 'quantity', 'unit_price', 'amount'],
        properties: {
          description: { type: 'string' },
          quantity: nullableNumber,
          unit_price: nullableNumber,
          amount: nullableNumber,
        },
      },
    },
    confidence: { type: 'number' },
    notes: nullableString,
  },
};

const systemPrompt = [
  'You are an expert accounts-payable assistant. Extract structured financial data from the supplied invoice, receipt or bill.',
  'Rules:',
  '- Never guess. If a value is not clearly present, return null.',
  '- vendor_name is the company that ISSUED the document (the seller/supplier), never the customer being billed.',
  '- Dates must be ISO format YYYY-MM-DD.',
  '- Amounts are plain numbers: no currency symbols, no thousands separators, use a dot as decimal separator.',
  '- total_amount is the final amount payable or paid, including tax.',
  `- currency is the 3-letter ISO code. If only a symbol is shown and it is ambiguous, use ${defaultCurrency}.`,
  `- category must be exactly one of: ${categories.join(', ')}.`,
  '- If the document is NOT an invoice, receipt or bill (newsletter, contract, marketing, etc.) set is_invoice_or_receipt to false.',
  '- confidence is 0 to 1 and reflects legibility and completeness of the extracted data.',
  '- description is a short one-line summary of what was purchased.',
].join('\n');

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const b64 = buf.toString('base64');

  const filePart = j.mimeType === 'application/pdf'
    ? { type: 'file', file: { filename: j.fileName || 'invoice.pdf', file_data: `data:application/pdf;base64,${b64}` } }
    : { type: 'image_url', image_url: { url: `data:${j.mimeType};base64,${b64}`, detail: 'high' } };

  out.push({
    json: {
      meta: {
        messageId: j.messageId, from: j.from, subject: j.subject, emailDate: j.emailDate,
        emailLink: j.emailLink, fileName: j.fileName, mimeType: j.mimeType,
      },
      requestBody: {
        model,
        temperature: 0,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: [{ type: 'text', text: 'Extract the financial data from this document.' }, filePart] },
        ],
        response_format: { type: 'json_schema', json_schema: { name: 'invoice_extraction', strict: true, schema } },
      },
    },
    pairedItem: { item: i },
  });
}
return out;

// Parses the AI response, normalises values, validates, and builds the duplicate key.
const cfg = $('⚙️ Workflow Config').first().json;
const defaultCurrency = String(cfg.defaultCurrency || 'USD').toUpperCase();
const minConfidence = Number(cfg.minConfidence ?? 0.6);
const responses = $input.all();
const requests = $('🧱 Build AI Request').all();
const out = [];

const clean = (v) => (v === null || v === undefined) ? '' : String(v).replace(/\s+/g, ' ').trim();
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
};
const isoDate = (v) => {
  const s = clean(v);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return '';
  const d = new Date(s + 'T00:00:00Z');
  return (!isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s) ? s : '';
};
const slug = (v) => clean(v).toLowerCase().replace(/[^a-z0-9]/g, '');

for (let i = 0; i < responses.length; i++) {
  const resp = responses[i].json || {};
  const meta = (requests[i] && requests[i].json.meta) || {};
  let data = {};
  let aiError = '';

  try {
    if (resp.error) throw new Error(typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error)));
    const msg = resp.choices && resp.choices[0] && resp.choices[0].message;
    if (msg && msg.refusal) throw new Error('AI refused: ' + msg.refusal);
    if (!msg || !msg.content) throw new Error('Empty AI response');
    data = JSON.parse(msg.content);
  } catch (e) {
    aiError = e.message || String(e);
  }

  const vendor = clean(data.vendor_name);
  const invoiceNumber = clean(data.invoice_number);
  const invoiceDate = isoDate(data.invoice_date);
  const dueDate = isoDate(data.due_date);
  const cur = clean(data.currency).toUpperCase();
  const currency = /^[A-Z]{3}$/.test(cur) ? cur : defaultCurrency;
  let subtotal = num(data.subtotal);
  const tax = num(data.tax_amount);
  let total = num(data.total_amount);
  if (total === null && subtotal !== null && tax !== null) total = Math.round((subtotal + tax) * 100) / 100;
  const confidence = Math.max(0, Math.min(1, Number(data.confidence) || 0));
  const category = clean(data.category) || 'Other';

  const lineItems = (Array.isArray(data.line_items) ? data.line_items : [])
    .map(li => `${clean(li.description)}${li.amount !== null && li.amount !== undefined ? ' — ' + li.amount : ''}`)
    .join(' | ').slice(0, 2000);

  // ---- validation ----
  const issues = [];
  if (aiError) issues.push('AI extraction failed: ' + aiError);
  else {
    if (data.is_invoice_or_receipt === false) issues.push('Document is not an invoice/receipt');
    if (!vendor) issues.push('Vendor name missing');
    if (total === null) issues.push('Total amount missing');
    else if (total <= 0) issues.push('Total is zero or negative (credit note?)');
    if (confidence < minConfidence) issues.push(`Low AI confidence (${confidence})`);
  }

  // ---- duplicate key ----
  const amountKey = total === null ? '0.00' : total.toFixed(2);
  const duplicateKey = invoiceNumber
    ? [slug(vendor), slug(invoiceNumber), amountKey, currency.toLowerCase()].join('|')
    : [slug(vendor), invoiceDate || 'nodate', amountKey, currency.toLowerCase()].join('|');

  out.push({
    json: {
      isValid: issues.length === 0,
      reviewReason: issues.join('; '),
      processedAt: new Date().toISOString(),
      vendor, invoiceNumber, invoiceDate, dueDate, currency,
      subtotal: subtotal === null ? '' : subtotal,
      tax: tax === null ? '' : tax,
      total: total === null ? '' : total,
      category,
      description: clean(data.description),
      lineItems,
      confidence,
      emailFrom: meta.from || '',
      emailSubject: meta.subject || '',
      emailDate: meta.emailDate || '',
      fileName: meta.fileName || '',
      emailLink: meta.emailLink || '',
      duplicateKey,
      rawAi: aiError ? ('ERROR: ' + aiError) : JSON.stringify(data).slice(0, 4000),
    },
    pairedItem: { item: i },
  });
}
return out;

// Compares every new invoice against the keys already stored in the Expenses sheet.
const clean = (v) => (v === null || v === undefined) ? '' : String(v).trim().toLowerCase();

const existing = new Set(
  $input.all().map(i => clean(i.json['Duplicate Key'])).filter(Boolean)
);

const incoming = $('✅ Valid Invoice?').all(0);
const seenInThisRun = new Set();
const out = [];

incoming.forEach((it, idx) => {
  const key = clean(it.json.duplicateKey);
  let isDuplicate = false;
  let duplicateReason = '';
  if (existing.has(key)) {
    isDuplicate = true;
    duplicateReason = 'Already exists in Expenses sheet';
  } else if (seenInThisRun.has(key)) {
    isDuplicate = true;
    duplicateReason = 'Duplicate within the same batch';
  }
  seenInThisRun.add(key);
  out.push({ json: { ...it.json, isDuplicate, duplicateReason }, pairedItem: { item: idx } });
});

return out;
